window.docContents[238].resolve({"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Untyped___typed-conversions--Typed-to-untyped":{"contents":"This direction is simpler in that it cannot fail since we're simply erasing compile-time type\ninformation.\n\nErases its type.\n\nFor example:\n\nopen Typed in\n#eval Env.runIO do\n  let x ← Term.mkSymbol \"x\"\n  let typedTerm ← smt! x ∨ false\n  --  ^^^^^^^^^~~~~~ `Typed.Term Bool`\n  println! \"typedTerm:  {typedTerm}\"\n  let erasedTerm := typedTerm.erase\n  --  ^^^^^^^^^^~~~~ `Untyped.Term`\n  println! \"erasedTerm: {erasedTerm}\"\n\n\ntypedTerm:  (or x false)\nerasedTerm: (or x false)\n\n\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Terms\u0009Untyped/typed conversions","header":"4.3.2. Typed to untyped","id":"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Untyped___typed-conversions--Typed-to-untyped"},"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Untyped___typed-conversions--Untyped-to-typed":{"contents":"The Untyped.Term.typeCheckAs type-checks at runtime an untyped term against (the sort\nassociated to) a static type to produce a typed term.\n\nTypes an untyped term.\n\nIf the term's type can be inferred from context, Untyped.Term.typeCheck is more concise\nalternative.\n\nTypes an untyped term.\n\nFor example:\n\nopen Untyped in\n#eval Env.runIO do\n  let bool ← Srt.bool\n  let x ← Term.mkSymbol bool \"x\"\n\n  let boolTerm ← smt! x ∨ false\n  println! \"boolTerm:  {boolTerm}\"\n\n  let typedTerm ← boolTerm.typeCheckAs Bool\n  println! \"typedTerm: {typedTerm}\"\n\n  let boolToInt (t : Typed.Term Bool) :=\n    smt! if t then 1 else 0\n  let iteTerm ← boolTerm.typeCheck >>= boolToInt\n  println! \"iteTerm:   {iteTerm}\"\n\n  println! \"\"\n  try\n    let illTypedTerm ← boolTerm.typeCheckAs Int\n    println! \"unexpected: {illTypedTerm}\"\n  catch e =>\n    println! \"{e}\"\n\n\nboolTerm:  (or x false)\ntypedTerm: (or x false)\niteTerm:   (ite (or x false) 1 0)\n\ncannot type the following term as `Int`, term has sort `Bool`:\n(or x false)\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Terms\u0009Untyped/typed conversions","header":"4.3.1. Untyped to typed","id":"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Untyped___typed-conversions--Untyped-to-typed"}});